// =====================================================================
// Email service (Integration & API Management Lead)
// Sends booking confirmation emails through the Resend API.
// Resend is a genuine third-party email service; the API key is stored
// in .env as RESEND_API_KEY and never committed to GitHub.
//
// The email embeds the QR ticket image generated by qrService, so the
// customer can show it at the venue for check-in.
// =====================================================================
const { Resend } = require('resend');
const { generateQRUrl } = require('./qrService');

const resend = new Resend(process.env.RESEND_API_KEY);

// Resend requires a verified sender. onboarding@resend.dev works for
// testing without owning a domain.
const FROM_ADDRESS = process.env.MAIL_FROM || 'onboarding@resend.dev';

function formatMYR(amount) {
  return `RM ${Number(amount).toFixed(2)}`;
}

function formatDateTime(value) {
  if (!value) return '-';
  const d = new Date(value);
  return d.toLocaleString('en-MY', {
    dateStyle: 'medium',
    timeStyle: 'short',
    timeZone: 'Asia/Kuala_Lumpur',
  });
}

/**
 * Build the HTML body for a booking confirmation email.
 * Kept as a separate function so it can be unit-tested and reused.
 */
function buildBookingEmailHtml({ customerName, booking, event, venue, schedule }) {
  const qrUrl = generateQRUrl(booking.booking_ref, '220x220');
  return `
  <div style="font-family:Arial,sans-serif;max-width:560px;margin:auto;color:#111">
    <h2 style="margin:0 0 4px">Ticket.exe — Booking confirmed</h2>
    <p style="margin:0 0 16px;color:#555">Hi ${customerName}, here is your e-ticket.</p>

    <table style="width:100%;border-collapse:collapse;margin-bottom:16px">
      <tr><td style="padding:6px 0;color:#555">Booking reference</td>
          <td style="padding:6px 0;text-align:right"><b>${booking.booking_ref}</b></td></tr>
      <tr><td style="padding:6px 0;color:#555">Event</td>
          <td style="padding:6px 0;text-align:right">${event.title}</td></tr>
      <tr><td style="padding:6px 0;color:#555">Venue</td>
          <td style="padding:6px 0;text-align:right">${venue.name}, ${venue.city}</td></tr>
      <tr><td style="padding:6px 0;color:#555">Date & time</td>
          <td style="padding:6px 0;text-align:right">${formatDateTime(schedule.start_time)}</td></tr>
      <tr><td style="padding:6px 0;color:#555">Quantity</td>
          <td style="padding:6px 0;text-align:right">${booking.quantity}</td></tr>
      <tr><td style="padding:6px 0;color:#555">Total</td>
          <td style="padding:6px 0;text-align:right"><b>${formatMYR(booking.total_amount)}</b></td></tr>
    </table>

    <div style="text-align:center;padding:16px;border:1px dashed #ccc;border-radius:8px">
      <p style="margin:0 0 8px;color:#555">Show this QR code at the entrance</p>
      <img src="${qrUrl}" alt="QR ticket" width="220" height="220" />
    </div>

    <p style="margin-top:16px;color:#888;font-size:12px">
      This is an automated message from Ticket.exe. Please do not reply.
    </p>
  </div>`;
}

/**
 * Send the booking confirmation email. Returns the Resend response
 * (or throws) so the caller can log the result.
 */
async function sendBookingConfirmation({ to, customerName, booking, event, venue, schedule }) {
  const html = buildBookingEmailHtml({ customerName, booking, event, venue, schedule });
  const subject = `Your ticket for ${event.title} (${booking.booking_ref})`;

  const result = await resend.emails.send({
    from: FROM_ADDRESS,
    to,
    subject,
    html,
  });

  // Resend returns { data: { id }, error } ; normalise for logging
  if (result.error) {
    throw new Error(`Resend error: ${result.error.message || JSON.stringify(result.error)}`);
  }
  return result.data;
}

module.exports = { sendBookingConfirmation, buildBookingEmailHtml };